:where(#eazybe-system337) #automation .oz-kicker{font:700 9px/1 Inter,Arial,sans-serif;letter-spacing:1.4px;text-transform:uppercase;color:#6d7584}
:where(#eazybe-system337) #automation .oz-pill{font:700 10px/1 Inter,Arial,sans-serif;letter-spacing:.4px;padding:6px 10px;border-radius:999px;background:#eef2ff;color:#3b55c4;white-space:nowrap}
