:where(#eazybe-system337) #automation .oz-stat{font:800 46px/1 Inter,Arial,sans-serif;letter-spacing:-1.5px;color:#1a2440}
:where(#eazybe-system337) #automation .oz-stat small{display:block;font:500 12px/1.5 Inter,Arial,sans-serif;letter-spacing:0;color:#6c7587;margin-top:7px}
:where(#eazybe-system337) #automation .oz-chips{display:flex;flex-wrap:wrap;gap:7px}
:where(#eazybe-system337) #automation .oz-chip{font:600 11px/1 Inter,Arial,sans-serif;padding:8px 11px;border-radius:9px;background:#f4f6fb;color:#50607c;display:inline-flex;align-items:center;gap:6px}
:where(#eazybe-system337) #automation .oz-chip b{color:#1f2b45;font-weight:700}
:where(#eazybe-system337) #automation .oz-chat{background:#ece5dd;border-radius:14px;padding:13px;display:flex;flex-direction:column;gap:8px}
:where(#eazybe-system337) #automation .oz-in,:where(#eazybe-system337) #automation .oz-out{max-width:86%;padding:9px 12px;border-radius:12px;font:400 12.5px/1.5 Inter,Arial,sans-serif;color:#2f3b30;box-shadow:0 1px 1px rgba(0,0,0,.07)}
:where(#eazybe-system337) #automation .oz-in{align-self:flex-start;background:#fff;border-bottom-left-radius:3px}
:where(#eazybe-system337) #automation .oz-out{align-self:flex-end;background:#d9fdd3;border-bottom-right-radius:3px}
:where(#eazybe-system337) #automation .oz-in time,:where(#eazybe-system337) #automation .oz-out time{display:block;text-align:right;font-size:8.5px;color:#667066;margin-top:4px}
:where(#eazybe-system337) #automation .oz-out b.tag{display:block;font:700 8.5px/1 Inter,Arial,sans-serif;letter-spacing:.8px;color:#1f7a4d;margin-bottom:4px}
:where(#eazybe-system337) #automation .oz-mark{background:#fff3c4;border-radius:4px;padding:0 3px;color:#7a5a00;font-weight:600}
:where(#eazybe-system337) #automation .oz-flow{display:grid;grid-template-columns:1fr 18px 1fr 18px 1fr;align-items:center;gap:6px}
:where(#eazybe-system337) #automation .oz-node{background:#f6f8fd;border:1px solid #e4e9f5;border-radius:12px;padding:12px 10px;text-align:center}
:where(#eazybe-system337) #automation .oz-node b{display:block;font:700 12px/1.3 Inter,Arial,sans-serif;color:#22304d}
:where(#eazybe-system337) #automation .oz-node small{display:block;font:500 10px/1.4 Inter,Arial,sans-serif;color:#666d7d;margin-top:4px}
:where(#eazybe-system337) #automation .oz-node.on{background:#eef2ff;border-color:#c7d2fb}
:where(#eazybe-system337) #automation .oz-node.done{background:#e8f6ee;border-color:#bfe4cd}
:where(#eazybe-system337) #automation .oz-arrow{text-align:center;color:#b3bdd2;font:700 13px/1 Inter,Arial,sans-serif}
:where(#eazybe-system337) #automation .oz-rows{display:flex;flex-direction:column;gap:8px}
:where(#eazybe-system337) #automation .oz-row{display:flex;align-items:center;gap:11px;padding:10px 12px;border-radius:12px;background:#f7f8fc}
:where(#eazybe-system337) #automation .oz-row.on{background:#eef2ff;box-shadow:inset 0 0 0 1px #c7d2fb}
:where(#eazybe-system337) #automation .oz-row.fade{opacity:.55}
:where(#eazybe-system337) #automation .oz-av{width:30px;height:30px;border-radius:50%;background:#dfe6fb;color:#3f52a0;display:grid;place-items:center;font:700 10.5px/1 Inter,Arial,sans-serif;flex:0 0 auto}
:where(#eazybe-system337) #automation .oz-row span{flex:1;font:600 12px/1.3 Inter,Arial,sans-serif;color:#28334c;min-width:0}
:where(#eazybe-system337) #automation .oz-row span i{display:block;font:500 10px/1.4 Inter,Arial,sans-serif;font-style:normal;color:#666d7d;margin-top:2px}
:where(#eazybe-system337) #automation .oz-row em{font:700 10px/1 Inter,Arial,sans-serif;font-style:normal;color:#5a6a86;white-space:nowrap}
:where(#eazybe-system337) #automation .oz-bars{display:flex;flex-direction:column;gap:11px}
:where(#eazybe-system337) #automation .oz-bar b{display:flex;justify-content:space-between;font:700 11.5px/1 Inter,Arial,sans-serif;color:#28334c;margin-bottom:6px}
:where(#eazybe-system337) #automation .oz-bar b span{color:#6c7587;font-weight:500}
:where(#eazybe-system337) #automation .oz-track{height:8px;border-radius:99px;background:#eef1f7;overflow:hidden}
:where(#eazybe-system337) #automation .oz-track i{display:block;height:100%;border-radius:99px;background:linear-gradient(90deg,#4263eb,#8aa6ff)}
:where(#eazybe-system337) #automation .oz-track i.g{background:linear-gradient(90deg,#1f9d62,#6ed0a0)}
:where(#eazybe-system337) #automation .oz-call{display:flex;align-items:center;gap:14px}
:where(#eazybe-system337) #automation .oz-call .oz-av{width:46px;height:46px;font-size:14px;background:#e7ecfd}
:where(#eazybe-system337) #automation .oz-call b{display:block;font:700 15px/1.2 Inter,Arial,sans-serif;color:#1d2a44}
:where(#eazybe-system337) #automation .oz-call small{display:block;font:500 11px/1.4 Inter,Arial,sans-serif;color:#666d7d;margin-top:3px}
:where(#eazybe-system337) #automation .oz-timer{margin-left:auto;font:700 13px/1 Inter,Arial,sans-serif;color:#3b55c4;font-variant-numeric:tabular-nums}
:where(#eazybe-system337) #automation .oz-wave{display:flex;align-items:center;gap:3px;height:34px}
:where(#eazybe-system337) #automation .oz-wave i{flex:1;border-radius:99px;background:#c3cfee;height:var(--h)}
:where(#eazybe-system337) #automation .outreach-scene.active .oz-wave i{animation:oz-wave 1.1s ease-in-out infinite alternate;animation-delay:calc(var(--i)*55ms);background:#8ea5e8}
@keyframes oz-wave{to{transform:scaleY(.35)}}
:where(#eazybe-system337) #automation .oz-foot{display:flex;align-items:center;gap:8px;font:600 11.5px/1.5 Inter,Arial,sans-serif;color:#1f7a4d;background:#eef8f2;border-radius:11px;padding:10px 13px}
:where(#eazybe-system337) #automation .oz-note{text-align:center;font:500 9px/1 Inter,Arial,sans-serif;letter-spacing:.4px;color:#575b65}
:where(#eazybe-system337) #automation .oz-cal{display:flex;align-items:center;gap:13px;background:#f6f8fd;border:1px solid #e4e9f5;border-radius:13px;padding:13px}
:where(#eazybe-system337) #automation .oz-cal div:first-child{text-align:center;background:#fff;border:1px solid #e4e9f5;border-radius:10px;padding:7px 11px}
:where(#eazybe-system337) #automation .oz-cal div:first-child small{display:block;font:700 9px/1 Inter,Arial,sans-serif;letter-spacing:1px;color:#8390ad}
:where(#eazybe-system337) #automation .oz-cal div:first-child b{display:block;font:800 20px/1.1 Inter,Arial,sans-serif;color:#1d2a44;margin-top:3px}
:where(#eazybe-system337) #automation .oz-cal b.t{font:700 13px/1.3 Inter,Arial,sans-serif;color:#1d2a44;display:block}
:where(#eazybe-system337) #automation .oz-cal small.s{font:500 11px/1.4 Inter,Arial,sans-serif;color:#666d7d;display:block;margin-top:3px}
:where(#eazybe-system337) #automation .oz-strike{text-decoration:line-through;color:#a3adc0}
